<template><AppShell><PageHeader :eyebrow="config.eyebrow" :title="config.title" :description="config.description"><button class="button"><Download :size="16"/> CSV 내보내기</button></PageHeader><section class="metric-grid summary-metrics"><article v-for="item in config.metrics" :key="item.label" class="metric card"><div class="metric-head"><span>{{ item.label }}</span><span class="metric-icon"><component :is="item.icon" :size="17"/></span></div><div><strong class="metric-value">{{ item.value }}</strong><p class="trend">{{ item.trend }}</p></div></article></section><section class="panel data-panel"><div class="table-toolbar"><div class="table-search"><Search :size="16"/><input :placeholder="config.search"/></div><select class="select"><option>전체 상태</option><option>활성</option><option>비활성</option></select><select class="select"><option>최신 등록순</option><option>이름순</option></select><button class="button small"><SlidersHorizontal :size="14"/> 상세 필터</button></div><div class="table-wrap"><table v-if="type==='companies'" class="data-table"><thead><tr><th>기업</th><th>사업자번호</th><th>대표 관리자</th><th>좌석</th><th>구독 상태</th><th>등록일</th><th></th></tr></thead><tbody><tr v-for="company in companies" :key="company.business"><td><div class="person"><span class="company-avatar">{{ company.name[0] }}</span><span><strong>{{ company.name }}</strong><span>COMP-{{ company.business.slice(0,3) }}</span></span></div></td><td>{{ company.business }}</td><td>{{ company.admin }}</td><td>{{ company.seats }}</td><td><span class="tag" :class="statusClass(company.subscription)">{{ company.subscription }}</span></td><td>{{ company.joined }}</td><td><button class="row-menu"><MoreHorizontal :size="17"/></button></td></tr></tbody></table><table v-else-if="type==='users'" class="data-table"><thead><tr><th>사용자</th><th>소속 기업</th><th>비즈니스 역할</th><th>수강</th><th>상태</th><th>가입일</th><th></th></tr></thead><tbody><tr v-for="(user,i) in userRows" :key="user.email"><td><div class="person"><span class="avatar">{{ user.name[0] }}</span><span><strong>{{ user.name }}</strong><span>{{ user.email }}</span></span></div></td><td>{{ i===4?'브릿지랩':'스칼라테크' }}</td><td><span class="tag gray">{{ i===0?'COMPANY_ADMIN':'EMPLOYEE' }}</span></td><td>{{ user.courses }}개</td><td><span class="tag" :class="user.status==='활성'?'':'gray'">{{ user.status }}</span></td><td>{{ user.joined }}</td><td><button class="row-menu"><MoreHorizontal :size="17"/></button></td></tr></tbody></table><table v-else-if="type==='payments'" class="data-table"><thead><tr><th>결제 ID</th><th>기업</th><th>요금제</th><th>결제일</th><th>금액</th><th>상태</th><th></th></tr></thead><tbody><tr v-for="payment in payments" :key="payment.id"><td><strong>{{ payment.id }}</strong></td><td>{{ payment.company }}</td><td>{{ payment.plan }}</td><td>{{ payment.date }}</td><td><strong>{{ payment.amount }}</strong></td><td><span class="tag" :class="payment.status==='결제 완료'?'':'red'">{{ payment.status }}</span></td><td><button class="row-menu"><MoreHorizontal :size="17"/></button></td></tr></tbody></table><table v-else class="data-table"><thead><tr><th>수강 ID</th><th>직원</th><th>소속 기업</th><th>강의</th><th>진도율</th><th>상태</th><th>시작일</th></tr></thead><tbody><tr v-for="(user,i) in userRows" :key="user.email"><td><strong>ENR-900{{ i+1 }}</strong></td><td>{{ user.name }}</td><td>스칼라테크</td><td>{{ courses[i%courses.length].title }}</td><td><div class="progress-cell"><div class="progress"><span :style="`width:${user.progress}%`"></span></div><b>{{ user.progress }}%</b></div></td><td><span class="tag" :class="user.progress>80?'blue':''">{{ user.progress>80?'COMPLETED':'LEARNING' }}</span></td><td>{{ user.joined }}</td></tr></tbody></table></div><div class="table-footer"><span>총 {{ config.total }}개 중 1–{{ rows }}개 표시</span><div><button><ChevronLeft :size="15"/></button><button class="active">1</button><button>2</button><button>3</button><button><ChevronRight :size="15"/></button></div></div></section></AppShell></template>
<script setup>import { computed } from 'vue'; import { Download,Search,SlidersHorizontal,MoreHorizontal,ChevronLeft,ChevronRight,Building2,BadgeCheck,AlertTriangle,UsersRound,UserCheck,UserRoundX,ReceiptText,CircleCheck,RefreshCw,GraduationCap,Trophy,BookOpen } from '@lucide/vue'; import AppShell from '@/components/AppShell.vue'; import PageHeader from '@/components/PageHeader.vue'; import { companies,employees,payments,courses } from '@/data/mockData.js'; const props=defineProps({type:{type:String,default:'companies'}}); const configs={companies:{eyebrow:'Company operations',title:'기업 관리',description:'가입 기업과 구독·좌석 상태를 조회합니다.',search:'기업명 또는 사업자번호 검색',total:128,metrics:[{label:'전체 기업',value:'128',trend:'이번 달 +12',icon:Building2},{label:'활성 구독',value:'119',trend:'전체의 93%',icon:BadgeCheck},{label:'확인 필요',value:'3',trend:'결제 실패 포함',icon:AlertTriangle},{label:'전체 좌석',value:'5,840',trend:'사용률 82%',icon:UsersRound}]},users:{eyebrow:'User operations',title:'사용자 관리',description:'플랫폼 사용자의 역할, 소속과 계정 상태를 조회합니다.',search:'이름 또는 이메일 검색',total:4892,metrics:[{label:'전체 사용자',value:'4,892',trend:'이번 달 +284',icon:UsersRound},{label:'활성 사용자',value:'4,621',trend:'활성률 94.5%',icon:UserCheck},{label:'기업 관리자',value:'136',trend:'기업당 평균 1.1명',icon:BadgeCheck},{label:'비활성 · 탈퇴',value:'271',trend:'이번 달 18명',icon:UserRoundX}]},payments:{eyebrow:'Payment operations',title:'결제 관리',description:'기업별 결제 결과와 구독 이벤트 상태를 조회합니다.',search:'결제 ID 또는 기업명 검색',total:936,metrics:[{label:'이번 달 결제',value:'₩38.2M',trend:'전월 대비 +8.4%',icon:ReceiptText},{label:'결제 성공',value:'127건',trend:'성공률 99.2%',icon:CircleCheck},{label:'결제 실패',value:'1건',trend:'확인 필요',icon:AlertTriangle},{label:'자동 갱신',value:'119건',trend:'다음 30일 예정',icon:RefreshCw}]},enrollments:{eyebrow:'Enrollment operations',title:'수강 관리',description:'전체 기업의 수강 상태와 서버 계산 진도율을 조회합니다.',search:'수강 ID, 직원 또는 강의 검색',total:7340,metrics:[{label:'전체 수강',value:'7,340',trend:'이번 달 +824',icon:GraduationCap},{label:'학습 중',value:'4,218',trend:'전체의 57.5%',icon:BookOpen},{label:'완료',value:'2,934',trend:'완료율 72.8%',icon:Trophy},{label:'평균 진도율',value:'68%',trend:'전월 대비 +5%',icon:CircleCheck}]}}; const config=computed(()=>configs[props.type]); const userRows=computed(()=>[{...employees[0],name:'김관리',email:'admin@scalatech.co.kr'},...employees]); const rows=computed(()=>props.type==='companies'?companies.length:props.type==='payments'?payments.length:userRows.value.length); function statusClass(status){return status==='ACTIVE'?'':status==='PAYMENT_FAILED'?'red':'amber'}</script>
<style scoped>.summary-metrics{margin-bottom:14px}.data-panel{padding:0;overflow:hidden}.table-toolbar{display:flex;gap:8px;padding:13px 16px;border-bottom:1px solid var(--line)}.table-search{width:270px;height:38px;display:flex;align-items:center;gap:8px;padding:0 10px;background:var(--surface-2);border-radius:9px;color:var(--muted)}.table-search input{width:100%;background:transparent;border:0;outline:0;font-size:10px}.table-toolbar .select{width:130px;min-height:38px;font-size:9px}.table-toolbar .button{margin-left:auto}.company-avatar{width:34px;height:34px;display:grid;place-items:center;color:var(--ink);background:var(--lime);border-radius:9px;font-size:11px;font-weight:800}.row-menu{color:var(--muted);background:transparent}.progress-cell{display:flex;align-items:center;gap:8px}.progress-cell .progress{width:70px}.progress-cell b{font-size:8px}.table-footer{display:flex;align-items:center;justify-content:space-between;padding:12px 16px;color:var(--muted);border-top:1px solid var(--line);font-size:8px}.table-footer>div{display:flex;gap:3px}.table-footer button{width:28px;height:28px;display:grid;place-items:center;color:var(--muted);background:transparent;border-radius:6px}.table-footer button.active{color:white;background:var(--forest)}@media(max-width:720px){.table-toolbar{flex-wrap:wrap}.table-search{width:100%}.table-toolbar .button{margin-left:0}}</style>
